    scrollHorizontal: function () {
        if (jQuery('.horizontal').length) {
            let horizontalSection = document.querySelector('.horizontal');
            let horizontalProgressBar = document.querySelector('.horizontal-progress-bar');
            let horizontalTween = gsap.to('.horizontal', {
                x: () => horizontalSection.scrollWidth * -1,
                xPercent: 100,
                scrollTrigger: {
                    trigger: '.horizontal',
                    start: 'center center',
                    end: '+=2000px',
                    pin: '.horizontal-scroll-wrapper',
                    scrub: true,
                    invalidateOnRefresh: true,
                    // markers: true,
                    onUpdate: (self) => {
                        if (horizontalProgressBar) {
                            gsap.set(horizontalProgressBar, { scaleX: self.progress });
                        }
                    }
                }
            });
        }
    },
