    handleSectionResort: function () {
        //equal height for two tab
        // function syncGalleryHeight() {
        //     var mapHeight = jQuery('.map-point').outerHeight();

        //     jQuery('.indoor_photo').height(mapHeight);
        // }
        // jQuery(window).on('load resize', function () {
        //     syncGalleryHeight();
        // });

        //handle tab
        jQuery('.resort_living .showcase-resort .tab-resort .nav-tabs .nav-link').on('click', function () {
            let tab = jQuery(this).data('tab');

            // active button
            jQuery('.resort_living .showcase-resort .tab-resort .nav-tabs .nav-link').removeClass('active');
            jQuery(this).addClass('active');

            // đổi content showcase
            jQuery('.tab-pane-custom')
                .removeClass('active');

            jQuery('.tab-pane-custom[data-content="' + tab + '"]')
                .addClass('active');

        });

        // Handle tab outdoor
        jQuery('.outdoor-control .btn-floor').on('click', function () {

            let outdoor = jQuery(this).data('outdoor');

            // Chỉ remove active của outdoor
            jQuery('.outdoor-control .btn-floor').removeClass('active');
            jQuery(this).addClass('active');

            jQuery('.outdoor-list')
                .removeClass('show')
                .filter('[data-outdoor="' + outdoor + '"]')
                .addClass('show');
        });


        // Handle tab indoor
        jQuery('.indoor-control .btn-floor').on('click', function () {

            let indoor = jQuery(this).data('indoor');

            // Chỉ remove active của indoor
            jQuery('.indoor-control .btn-floor').removeClass('active');
            jQuery(this).addClass('active');

            jQuery('.indoor-list')
                .removeClass('show')
                .filter('[data-indoor="' + indoor + '"]')
                .addClass('show');
            jQuery('.map-amenity')
                .removeClass('show')
                .filter('[data-indoor="' + indoor + '"]')
                .addClass('show');
        });


        //click point
        jQuery(function () {
            function setActive(id) {
                jQuery('.detail-resort .list-point li').removeClass('active');
                jQuery('.tab-content-showcase .point-element').removeClass('active');
                jQuery('.tab-content-showcase .point-element[data-id="' + id + '"]').addClass('active');
                jQuery('.detail-resort .list-point li[data-id="' + id + '"]').addClass('active');
            }
            // Click trên danh sách
            jQuery(document).on('click', '.detail-resort .list-point li a', function (e) {
                e.preventDefault();

                let id = jQuery(this).closest('li').data('id');

                setActive(id);
            });
            // Click ngoài vùng point và list thì bỏ active
            jQuery(document).on('click', function (e) {
                if (!jQuery(e.target).closest('.detail-resort .list-point, .tab-content-showcase .point-element').length) {
                    jQuery('.detail-resort .list-point li').removeClass('active');
                    jQuery('.tab-content-showcase .point-element').removeClass('active');
                }
            });

        });

    },
