    sliderDesign: function () {
        var $slider = jQuery('.slider_design');
        var $counter = jQuery('.number-slide');

        function updateCounter(slick, current) {
            $counter.html(`
            <span class="current">${current + 1}</span>
            <span class="slash">/</span>
            <span class="total">${slick.slideCount}</span>
        `);
        }
        $slider.on('init', function (event, slick) {
            updateCounter(slick, 0);
        });
        $slider.on('afterChange', function (event, slick, currentSlide) {
            updateCounter(slick, currentSlide);
        });

        $slider.slick({
            slidesToShow: 1,
            slidesToScroll: 1,
            dots: true,
            arrows: true,
            infinite: true,
            autoplay: false,
            speed: 800,
            autoplaySpeed: 2000,
            fade: false,
            prevArrow: '.slide_design-wrapper .arr-design.left',
            nextArrow: '.slide_design-wrapper .arr-design.right',
            asNavFor: '.slider_detail-design'
        });
        jQuery('.slider_detail-design').slick({
            slidesToShow: 1,
            slidesToScroll: 1,
            dots: false,
            arrows: false,
            infinite: true,
            autoplay: false,
            speed: 800,
            autoplaySpeed: 2000,
            fade: true,
            asNavFor: $slider,
            adaptiveHeight: true
        });
    },
    sectionFloorPlan: function () {
        //handle tab
        jQuery('.site_plan .table_plan .tab-plan .nav-tabs .nav-link').on('click', function () {
            let tab = jQuery(this).data('tab');

            // active button
            jQuery('.site_plan .table_plan .tab-plan .nav-tabs .nav-link').removeClass('active');
            jQuery(this).addClass('active');

            // đổi content showcase
            jQuery('.tab-pane-plan')
                .removeClass('active');

            jQuery('.tab-pane-plan[data-content="' + tab + '"]')
                .addClass('active');

        });

        //handle tab list room unit plan
        jQuery('.site_plan .table_plan .list_tab-room .btn-room').on('click', function () {

            let room = jQuery(this).data('room');

            jQuery('.btn-room').removeClass('active');
            jQuery(this).addClass('active');

            jQuery('.wrap-infor-plan')
                .removeClass('show')
                .filter('[data-room="' + room + '"]')
                .addClass('show');

            // Mobile: scroll xuống phần thông tin
            if (window.innerWidth < 1026) {
                jQuery('html, body').animate({
                    scrollTop: jQuery('.tab-pane-plan.active').offset().top + 300
                }, 0);
            }
        });
        //handle tab list room floor plan
        jQuery('.site_plan .table_plan .list_tab-room .btn-tower').on('click', function () {

            let tower = jQuery(this).data('tower');

            jQuery('.btn-tower').removeClass('active');
            jQuery(this).addClass('active');

            jQuery('.wrap-infor-tower')
                .removeClass('show')
                .filter('[data-tower="' + tower + '"]')
                .addClass('show');

            // Mobile: scroll xuống phần thông tin
            if (window.innerWidth < 1026) {
                jQuery('html, body').animate({
                    scrollTop: jQuery('.tab-pane-plan.active').offset().top + 300
                }, 0);
            }
        });

        //handle tab 2 bedroom
        jQuery('.site_plan .wrap-infor-plan .infor_plan .tab_entire .btn-type').on('click', function () {

            let tab = jQuery(this).attr('data-bedroom');
            // lấy wrap hiện tại
            let wrap = jQuery(this).closest('.wrap-infor-plan');
            // active button trong đúng wrap
            wrap.find('.tab_entire .btn-type').removeClass('active');
            jQuery(this).addClass('active');

            // đổi thông tin trong đúng wrap
            wrap.find('.infor_bedroom').removeClass('active');

            wrap.find('.infor_bedroom[data-bedroom="' + tab + '"]')
                .addClass('active');


            // đổi hình trong đúng wrap
            wrap.find('.photo_plan_bedroom').removeClass('active');

            wrap.find('.photo_plan_bedroom[data-bedroom="' + tab + '"]')
                .addClass('active');

        });
    },
