//slider gallery
function initGallerySlider() {

    var $thumb = jQuery('.slider_thumb-gallery');
    var $photo = jQuery('.slider_photo-gallery');

    function updateCounter(slick, currentSlide) {

        jQuery('.current-slide').text((currentSlide || 0) + 1);

        jQuery('.total-mini-album').text(slick.slideCount);

    }

    $photo.on('init afterChange', function (e, slick, currentSlide) {

        updateCounter(slick, currentSlide);

    });

    $photo.slick({

        slidesToShow: 1,
        slidesToScroll: 1,
        fade: true,
        arrows: false,
        swipe: false,
        draggable: false,
        touchMove: false,
        asNavFor: '.slider_thumb-gallery'

    });

    $thumb.slick({

        slidesToShow: 8,
        slidesToScroll: 1,
        vertical: true,
        verticalSwiping: true,
        focusOnSelect: true,
        arrows: true,
        asNavFor: '.slider_photo-gallery',
        prevArrow: '.arr-thumb-top',
        nextArrow: '.arr-thumb-down',
        responsive: [
            {
                breakpoint: 1025,
                settings: {
                    vertical: false,
                    verticalSwiping: false
                }
            },
            {
                breakpoint: 600,
                settings: {
                    slidesToShow: 4,
                    vertical: false,
                    verticalSwiping: false
                }
            },
            {
                breakpoint: 480,
                settings: {
                    slidesToShow: 4,
                    vertical: false,
                    verticalSwiping: false
                }
            }
        ]

    });

}

// ĐẶT ĐOẠN NÀY Ở ĐÂY
jQuery('#galleryModal').on('shown.bs.modal', function () {

    if (jQuery('.slider_thumb-gallery').hasClass('slick-initialized')) {
        jQuery('.slider_thumb-gallery').slick('setPosition');
    }

    if (jQuery('.slider_photo-gallery').hasClass('slick-initialized')) {
        jQuery('.slider_photo-gallery').slick('setPosition');
    }

});


jQuery(document).on('click', '.open-gallery', function () {

    let id = jQuery(this).data('post-id');

    jQuery.ajax({

        url: gallery_ajax.ajax_url,

        type: 'POST',

        data: {
            action: 'load_gallery',
            post_id: id
        },

        success: function (res) {

            if (!res.success) return;


            // Title
            jQuery('.gallery-title').text(res.data.title);


            // Content
            jQuery('.gallery-content').html(res.data.content);



            let photoHtml = '';
            let thumbHtml = '';


            jQuery.each(res.data.photos, function (i, url) {


                photoHtml += `
                    <div>
                        <figure>
                            <img src="${url}" class="img-fluid">
                        </figure>
                    </div>
                `;


                thumbHtml += `
                    <div class="thumb-item">
                        <img src="${url}" class="img-fluid">
                    </div>
                `;


            });



            let $photo = jQuery('.slider_photo-gallery');
            let $thumb = jQuery('.slider_thumb-gallery');


            // destroy slick cũ
            if ($photo.hasClass('slick-initialized')) {
                $photo.slick('unslick');
            }


            if ($thumb.hasClass('slick-initialized')) {
                $thumb.slick('unslick');
            }



            // append data mới

            $photo.html(photoHtml);

            $thumb.html(thumbHtml);



            // init lại slider

            initGallerySlider();


            setTimeout(function () {

                $photo.slick('setPosition');
                $thumb.slick('setPosition');

            }, 0);



        }

    });

});
