(function() {
  // Automatic cloud fallback if palm-river.html is moved without the /assets/palm-river/ directory
  window.addEventListener('error', function(e) {
    var el = e.target;
    if (!el || !el.tagName) return;
    var attr = el.getAttribute('src');
    if (attr && attr.indexOf('/assets/palm-river/') === 0 && !el.dataset.cloudFallback) {
      el.dataset.cloudFallback = '1';
      el.src = 'https://palm-city.com.vn/palm-river/wp-content/' + attr.slice('/assets/palm-river/'.length);
      if (el.tagName === 'SOURCE' && el.parentElement && el.parentElement.load) {
        el.parentElement.load();
      }
    }
  }, true);

  // Ensure section navigation links (.js-scroll-section) smooth-scroll locally without navigating away
  jQuery(document).ready(function($) {
    $('.js-scroll-section').off('click').on('click', function(e) {
      var href = $(this).attr('href') || '';
      var hashIdx = href.indexOf('#');
      if (hashIdx !== -1) {
        var hash = href.slice(hashIdx);
        var $target = $(hash);
        if ($target.length) {
          e.preventDefault();
          $('.tab_menu-icon').removeClass('active');
          $('.short-menu').removeClass('move-top');
          $('.wrap-section-menu').removeClass('active');
          $('body').removeClass('menu-open');
          setTimeout(function() {
            $('html, body').animate({
              scrollTop: $target.offset().top
            }, 0);
          }, 0);
        }
      }
    });

    // Also allow clicking directly on map amenity pins (.point-element) to highlight both pin and list item
    $(document).on('click', '.tab-content-showcase .point-element', function(e) {
      e.stopPropagation();
      var id = $(this).data('id');
      if (id !== undefined) {
        $('.detail-resort .list-point li').removeClass('active');
        $('.tab-content-showcase .point-element').removeClass('active');
        $('.tab-content-showcase .point-element[data-id="' + id + '"]').addClass('active');
        $('.detail-resort .list-point li[data-id="' + id + '"]').addClass('active');
      }
    });

    // Refresh ScrollTrigger once all images/videos/fonts finish loading
    $(window).on('load', function() {
      if (window.ScrollTrigger) {
        ScrollTrigger.refresh();
      }
    });
  });

  // Local Contact Form 7 handler so form submission works offline / on file:// protocol
  document.addEventListener('submit', function(e) {
    var form = e.target;
    if (!form || !form.classList || !form.classList.contains('wpcf7-form')) return;
    if (window.location.hostname === 'palm-city.com.vn') return;

    e.preventDefault();
    e.stopImmediatePropagation();

    var out = form.querySelector('.wpcf7-response-output');
    var reqSelect = form.querySelector('[name="select-request"]');
    var nameInput = form.querySelector('[name="your-name"]');
    var emailInput = form.querySelector('[name="your-email"]');
    var phoneInput = form.querySelector('[name="your-phone"]');

    var valid = true;
    var errMsg = 'Một hoặc nhiều mục có lỗi. Vui lòng kiểm tra và thử lại.';
    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    var phoneRegex = /^[0-9+()\s.-]{8,15}$/;

    [reqSelect, nameInput, emailInput, phoneInput].forEach(function(field) {
      if (!field) return;
      var val = (field.value || '').trim();
      var fieldInvalid = !val;
      if (val && field === emailInput && !emailRegex.test(val)) {
        fieldInvalid = true;
      }
      if (val && field === phoneInput && !phoneRegex.test(val)) {
        fieldInvalid = true;
      }
      field.setAttribute('aria-invalid', fieldInvalid ? 'true' : 'false');
      if (fieldInvalid) valid = false;
    });

    if (!valid) {
      form.classList.remove('init', 'sent', 'submitting');
      form.classList.add('invalid');
      form.setAttribute('data-status', 'invalid');
      if (out) {
        out.textContent = errMsg;
        out.setAttribute('aria-hidden', 'false');
        out.style.display = 'block';
      }
    } else {
      form.classList.remove('init', 'invalid', 'submitting');
      form.classList.add('sent');
      form.setAttribute('data-status', 'sent');
      if (out) {
        out.textContent = 'Cảm ơn bạn đã gửi thông tin. Chúng tôi sẽ liên hệ lại trong thời gian sớm nhất.';
        out.setAttribute('aria-hidden', 'false');
        out.style.display = 'block';
      }
      form.reset();
    }
  }, true);
})();
;
(function() {
  function initLazyMediaAndScrollRefresh() {
    var lazyVideos = document.querySelectorAll("video[data-lazy-video]");
    function loadVideoSources(video) {
      if (video.dataset.lazyLoaded) return;
      video.dataset.lazyLoaded = "1";
      var sources = video.querySelectorAll("source[data-src]");
      sources.forEach(function(srcEl) {
        srcEl.setAttribute("src", srcEl.getAttribute("data-src"));
      });
      video.load();
    }
    function safePlay(video) {
      var p = video.play();
      if (p && typeof p.catch === "function") p.catch(function() {});
    }
    if ("IntersectionObserver" in window) {
      if (lazyVideos.length) {
        var loadObserver = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting) {
              loadVideoSources(entry.target);
              safePlay(entry.target);
              loadObserver.unobserve(entry.target);
            }
          });
        }, { rootMargin: "600px 0px" });
        lazyVideos.forEach(function(v) { loadObserver.observe(v); });
      }
      var allAutoplayVideos = document.querySelectorAll("video[autoplay]");
      if (allAutoplayVideos.length) {
        var playObserver = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            var v = entry.target;
            if (entry.isIntersecting) {
              if (v.dataset.lazyVideo && !v.dataset.lazyLoaded) {
                loadVideoSources(v);
              }
              if (v.paused) safePlay(v);
            } else {
              if (!v.paused) v.pause();
            }
          });
        }, { rootMargin: "150px 0px", threshold: 0.01 });
        allAutoplayVideos.forEach(function(v) { playObserver.observe(v); });
      }
    } else {
      lazyVideos.forEach(function(v) {
        loadVideoSources(v);
        safePlay(v);
      });
    }

    var refreshTimer = null;
    document.addEventListener("load", function(e) {
      var t = e.target;
      if (t && t.tagName === "IMG" && t.getAttribute("loading") === "lazy") {
        if (refreshTimer) clearTimeout(refreshTimer);
        refreshTimer = setTimeout(function() {
          if (window.ScrollTrigger && typeof window.ScrollTrigger.refresh === "function") {
            window.ScrollTrigger.refresh();
          }
        }, 180);
      }
    }, true);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initLazyMediaAndScrollRefresh);
  } else {
    initLazyMediaAndScrollRefresh();
  }
})();